-- R12 · Edició de publicacions editorials existents. Depén de 2610061448.
-- La fila app_content és la unitat CAS; no es creen pàgines ni s'admeten claus d'autoritat.
begin;
create or replace function public.admin_actualitza_publicacio_editorial(p_seccio text,p_id text,p_canvis jsonb,p_versio integer,p_tenant_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare clau text; fila public.app_content; element jsonb; nou jsonb; patch jsonb; entrada record; maxim integer; n integer; modificat jsonb; invalida_traduccions boolean:=false;
begin
  if not coalesce((select private.es_superadmin()),false) then
    raise exception 'SDP-ADMIN-003: cal superadmin amb aal2.' using errcode='42501';
  end if;
  clau:=case p_seccio when 'mur' then 'feedPosts' when 'events' then 'events' when 'mercat' then 'marketItems' when 'pagines' then 'pages' end;
  if clau is null or p_id is null or p_id !~ '^[A-Za-z0-9_-]{1,128}$' or p_versio is null or p_versio<1 or p_versio>=2147483647
    or p_tenant_id is null or jsonb_typeof(p_canvis) is distinct from 'object' or p_canvis='{}'::jsonb or octet_length(p_canvis::text)>750000 then
    raise exception 'SDP-EDITORIAL-001: canvis invàlids.' using errcode='22023';
  end if;
  for entrada in select key,value from jsonb_each(p_canvis) loop
    if p_seccio='pagines' then
      maxim:=case entrada.key when 'title' then 1000 when 'subtitle' then 2000 when 'lead' then 10000 when 'html' then 524288 when 'image' then 262144 when 'logo_image' then 262144 when 'logo_image_dark' then 262144 when 'copyright' then 1000 when 'icon' then 128 when 'publish_date' then 64 when 'categories' then 100 when 'tags' then 100 end;
    else
      maxim:=case entrada.key when 'title' then 1000 when 'subtitle' then 2000 when 'post_subtitle' then 2000 when 'entradilla' then 10000 when 'content' then 524288 when 'image_url' then 262144 when 'hero_image' then 262144 when 'logo_image' then 262144 when 'logo_image_dark' then 262144 when 'copyright' then 1000 when 'icon' then 128 when 'publish_date' then 64 when 'categories' then 100 when 'tags' then 100 end;
    end if;
    if maxim is null then raise exception 'SDP-EDITORIAL-001: camp no admés.' using errcode='22023'; end if;
    if entrada.key in ('categories','tags') then
      if jsonb_typeof(entrada.value) is distinct from 'array' then raise exception 'SDP-EDITORIAL-001: llista invàlida.' using errcode='22023'; end if;
      if jsonb_array_length(entrada.value)>100 or exists(select 1 from jsonb_array_elements(entrada.value) v where jsonb_typeof(v) is distinct from 'string' or length(v#>>'{}')>200) then raise exception 'SDP-EDITORIAL-001: llista invàlida.' using errcode='22023'; end if;
    elsif jsonb_typeof(entrada.value) is distinct from 'string' or length(entrada.value#>>'{}')>maxim then
      raise exception 'SDP-EDITORIAL-001: text invàlid.' using errcode='22023';
    end if;
  end loop;
  select * into fila from public.app_content where tenant_id=p_tenant_id and key=clau for update;
  if not found or jsonb_typeof(fila.payload) is distinct from 'array' then raise exception 'SDP-EDITORIAL-004: publicació absent.' using errcode='P0002'; end if;
  if fila.version<>p_versio then raise exception 'SDP-ADMIN-006: conflicte de versió.' using errcode='40001'; end if;
  select count(*) into n from jsonb_array_elements(fila.payload) v where v->>'id'=p_id;
  if n<>1 then raise exception 'SDP-EDITORIAL-004: publicació absent o duplicada.' using errcode='P0002'; end if;
  select value into element from jsonb_array_elements(fila.payload) where value->>'id'=p_id;
  invalida_traduccions:=p_seccio='pagines' and exists(select 1 from jsonb_each(p_canvis) v where v.key in ('title','subtitle','lead','html') and element->v.key is distinct from v.value);
  patch:=p_canvis;
  if invalida_traduccions then patch:=patch||jsonb_build_object('contentLanguage','ca'); end if;
  if patch ? 'content' or patch ? 'html' then patch:=patch||jsonb_build_object('editorial_format','html-r6'); end if;
  if p_seccio<>'pagines' and patch ? 'subtitle' then patch:=patch||jsonb_build_object('post_subtitle',patch->'subtitle'); end if;
  if patch ? 'image_url' then patch:=patch||jsonb_build_object('image',patch->'image_url','imageSrc',patch->'image_url'); end if;
  select coalesce(jsonb_agg(case when value->>'id'=p_id then (case when invalida_traduccions then value-'translations'-'i18n' else value end)||patch||jsonb_build_object('updated_at',clock_timestamp()) else value end order by ord),'[]'::jsonb)
    into nou from jsonb_array_elements(fila.payload) with ordinality as item(value,ord);
  update public.app_content set payload=nou,version=version+1 where tenant_id=p_tenant_id and key=clau returning * into fila;
  select value into modificat from jsonb_array_elements(fila.payload) where value->>'id'=p_id;
  -- El mateix RPC manté el mirall públic del Node0 coherent dins la transacció.
  -- El Node0 pilot és d'un sol tenant: el mateix NODE0_AUTH_TENANT que auth-node0.mjs.
  -- Supabase no té l'esquema node0 i no executa esta branca.
  if to_regclass('node0.public_documents') is not null and p_tenant_id='ac3bec76-255b-5ca2-8886-28fcceab4267'::uuid then
    execute 'update node0.public_documents d set document=v.value||jsonb_build_object(''_editorialClau'',$1,''_editorialVersio'',$2) from jsonb_array_elements($3) v(value) where d.kind=$1 and d.id=v.value->>''id''' using clau,fila.version,fila.payload;
  end if;
  return jsonb_build_object('item',modificat||jsonb_build_object('_editorialClau',clau,'_editorialVersio',fila.version),'versio',fila.version);
end;
$$;
revoke execute on function public.admin_actualitza_publicacio_editorial(text,text,jsonb,integer,uuid) from public,anon;
grant execute on function public.admin_actualitza_publicacio_editorial(text,text,jsonb,integer,uuid) to authenticated;
-- Backfill CAS del resum/absència coneguts de R5; qualsevol edició divergent es conserva.
DO $backfill$
DECLARE source0 record; row0 public.app_content; next0 jsonb;
BEGIN
 FOR source0 IN SELECT * FROM (VALUES ('feedPosts','manifest-de-poble','El Manifest de Poble és un document obert que analitza la problemàtica dels xicotets pobles rurals de l’Alcoià, el Comtat i les Marines i planteja solucions i escenaris de millora. El despoblament i l’abandonament de l’agricultura són els seus dos pilars. Consulta el Manifest, aporta propostes locals i coneix l’Aplec pel Territori de Benillup.','<h3>Un document obert dels pobles</h3>
<a href="https://drive.google.com/file/d/17H8EY4LTWlImwiusvuXlhv9ScpG3iE9M/view?usp=sharing" target="_blank" rel="noopener noreferrer"><img src="/assets/mur/manifest-de-poble/logo-manifest-de-poble-retallat.webp" alt="Logotip del Manifest de Poble" width="1024" height="891" loading="lazy" decoding="async"></a>
<p>És un <strong>document obert</strong> que <strong>analitza la problemàtica dels xicotets pobles rurals de les comarques de l’Alcoià, el Comtat i les Marines i planteja solucions i escenaris de millora. Es poden fer comentaris al PDF</strong>, i a totes les pàgines hi ha la data de revisió. Està previst fer un <a href="/events/aplec-2023">Aplec pel Territori</a> en gener per completar aquest Manifest i canalitzar les nostres demandes.</p>
<div class="manifest-de-poble__documents sdp-accions">
<a class="sdp-boto sdp-boto--secundari" href="https://drive.google.com/file/d/17H8EY4LTWlImwiusvuXlhv9ScpG3iE9M/view?usp=sharing" target="_blank" rel="noopener noreferrer">Llegir el Manifest de Poble (PDF)</a>
<a class="sdp-boto sdp-boto--secundari" href="https://docs.google.com/document/d/1_6HZhtCiCfVywoLJLzaRl4DbEoVSg1liLMB_vTz512U/edit?usp=sharing" target="_blank" rel="noopener noreferrer">Propostes locals al Manifest de Poble</a>
</div>
<a href="https://drive.google.com/file/d/17H8EY4LTWlImwiusvuXlhv9ScpG3iE9M/view?usp=sharing" target="_blank" rel="noopener noreferrer"><img src="/assets/mur/manifest-de-poble/Manifest_de_Poble_1.webp" alt="Primera pàgina del Manifest de Poble; el document complet es pot consultar en PDF" width="1600" height="2262" loading="lazy" decoding="async"></a>
<p>Primera pàgina del Manifest. Consulta el PDF per a llegir-lo complet i comprovar la data de cada revisió.</p>
<h3>Dos pilars per a revitalitzar els pobles</h3>
<p><strong>Arran de l’incendi d’Ebo en l’estiu del 2022 on es van cremar 12.000 ha i molts pobles van ser desallotjats, hem decidit unir esforços per posar fil a l’agulla i començar a treballar pel vertader problema dels pobles menuts mediterranis:</strong></p>
<h4>Despoblament</h4>
<h4>Abandonament de l’agricultura</h4>
<p class="sdp-paragraf-centrat"><strong>Revitalitzant estos aspectes, la resta fluirà sol!</strong></p>
<p>La <a href="http://zona14.org" target="_blank" rel="noopener noreferrer"><strong>Coordinadora d’Estudis Eòlics</strong></a> i l’<a href="/rentonar"><strong>Associació El Rentonar</strong></a> amb el <a href="/socdepoble"><strong>Projecte Soc de Poble</strong></a> proposem a tots els <strong>pobles d’interior i menuts</strong> de les comarques de l’<strong>Alcoià, Comtat i Marines del País Valencià</strong> fer un <a href="https://drive.google.com/file/d/17H8EY4LTWlImwiusvuXlhv9ScpG3iE9M/view?usp=sharing" target="_blank" rel="noopener noreferrer"><strong>llistat individualitzat d’exigències</strong></a>.</p>
<a href="https://www.facebook.com/aplecpelterritori" target="_blank" rel="noopener noreferrer"><img src="/assets/events/aplec-2023/socdepoble_facebook-128x128-1.png" alt="Aplec pel Territori al Facebook" width="128" height="128" loading="lazy" decoding="async"></a>
<p>Aplec pel Territori al Facebook</p>
<p>Les <strong>característiques puntuals</strong> són diferents, en <strong>turisme</strong>, en <strong>envelliment</strong>, en <strong>comunicacions</strong>, en proximitat a grans nuclis, en <strong>serveis bàsics</strong>… però les <strong>línies estratègiques conductores</strong> que ens afecten a tots els pobles són els que recull aquest manifest. Els sotasignats som <strong>associacions amb llarga trajectòria</strong> en la defensa del territori i del nostre patrimoni natural i humà vinculat sobre tot al <strong>món rural</strong>.</p>
<h3>Vertebrar-nos és crucial per a entendre que som els garants de la custòdia del territori!</h3>
<p class="sdp-paragraf-centrat"><strong>Posa’t en contacte amb la Comissió Redactora si creus que pots aportar!</strong></p>
<div class="manifest-de-poble__organitzadores">
<a href="http://zona14.org" target="_blank" rel="noopener noreferrer"><img src="/assets/events/aplec-2023/logo-coordinadora-circular-300x300.jpg" alt="Coordinadora d’Estudis Eòlics del Comtat" width="300" height="300" loading="lazy" decoding="async"></a>
<a href="/rentonar"><img src="/assets/events/aplec-2023/logo-rentonar-300x300.png" alt="Associació El Rentonar" width="300" height="300" loading="lazy" decoding="async"></a>
<a href="/socdepoble"><img src="/assets/events/aplec-2023/logo-socdepoble-300x300.png" alt="Projecte Sóc de Poble" width="300" height="300" loading="lazy" decoding="async"></a>
</div>
<h3>Un Aplec per a completar el Manifest</h3>
<p>Està previst fer un <a href="/events/aplec-2023"><strong>Aplec pel Territori</strong></a> en gener per <strong>completar aquest Manifest</strong> i <strong>canalitzar les nostres demandes</strong>.</p>
<a href="/events/aplec-2023"><img src="/assets/events/aplec-2023/aplec-pel-territori-2023-A4-1900px-1.jpg" alt="Cartell A4 del 2n Aplec pel Territori" width="1343" height="1900" loading="lazy" decoding="async"></a>
<p><a href="/events/aplec-2023">Aplec pel Territori</a>. Diumenge, 29 de gener, a les 10.30. Benillup. Convocatòria històrica de 2023.</p>
<a href="/assets/events/aplec-2023/ponents-aplec-2023-1900px.jpg" target="_blank" rel="noopener noreferrer"><img src="/assets/events/aplec-2023/ponents-aplec-2023-1900px.jpg" alt="Cartell dels ponents del 2n Aplec pel Territori" width="1343" height="1900" loading="lazy" decoding="async"></a>
<div class="sdp-subtargeta manifest-de-poble__adhesio" data-sdp-subtargeta="">
<h3>Formulari d’Adhesió al Manifest de Poble</h3>
<p><strong>També pots firmar baix.</strong> El botó d’<strong>adhesió</strong> obri el formulari extern en una altra pestanya per a poder continuar llegint esta pàgina.</p>
<div class="sdp-accions"><a class="sdp-boto sdp-boto--primari" href="https://forms.gle/g9TZ75WPwgGHrP8H7" target="_blank" rel="noopener noreferrer">Adherir-me al Manifest de Poble <span class="sdp-sr-only">(s’obri en una altra pestanya)</span></a></div>
</div>
<h3>Font original i avís de drets</h3>
<p><a href="https://socdepoble.net/2022/11/17/manifest-de-poble/" target="_blank" rel="noopener noreferrer"><strong>Sóc de Poble · Manifest de Poble</strong></a>, WordPress <strong>16893</strong>, publicat el 17 de novembre de 2022. Es conserven el text, les figures i els enllaços de la font amb maquetació <strong>Pedra Seca</strong>; el formulari extern es mostra com un enllaç accessible. <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener noreferrer"><strong>CC BY-NC-SA 4.0 Sóc de Poble</strong></a>.</p>'),
('events','aplec-2023',NULL,'<h3 class="detail-content__titol">El 2n Aplec a À Punt NTC</h3>
<p class="detail-content__paragraph">Reportatge d’<strong>À Punt NTC</strong> sobre l’Aplec del 29 de gener de 2023. <a href="https://www.youtube.com/watch?v=TlZWYbnGuCE" rel="noopener noreferrer" target="_blank">Obri el vídeo a YouTube</a>. Les gravacions històriques de Facebook es poden consultar a <a href="https://www.facebook.com/aplecpelterritori" rel="noopener noreferrer" target="_blank">l’arxiu de l’Aplec</a>.</p>
<h3 class="detail-content__titol">25 fotografies de l’Aplec a Benillup</h3>
<div class="aplec-2023__galeria"><div data-wp-media-id="17052"><img alt="2n Aplec pel Territori a Benillup · fotografia 1 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.33-1-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 1</p></div><div data-wp-media-id="17047"><img alt="2n Aplec pel Territori a Benillup · fotografia 2 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.33-2-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 2</p></div><div data-wp-media-id="17051"><img alt="2n Aplec pel Territori a Benillup · fotografia 3 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.33-3-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 3</p></div><div data-wp-media-id="17048"><img alt="2n Aplec pel Territori a Benillup · fotografia 4 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.33-4-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 4</p></div><div data-wp-media-id="17072"><img alt="2n Aplec pel Territori a Benillup · fotografia 5 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.33-5-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 5</p></div><div data-wp-media-id="17049"><img alt="2n Aplec pel Territori a Benillup · fotografia 6 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.33-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 6</p></div><div data-wp-media-id="17065"><img alt="2n Aplec pel Territori a Benillup · fotografia 7 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.34-1-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 7</p></div><div data-wp-media-id="17062"><img alt="2n Aplec pel Territori a Benillup · fotografia 8 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.34-2-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 8</p></div><div data-wp-media-id="17058"><img alt="2n Aplec pel Territori a Benillup · fotografia 9 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.34-3-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 9</p></div><div data-wp-media-id="17044"><img alt="2n Aplec pel Territori a Benillup · fotografia 10 de l’arxiu del 29 de gener de 2023" decoding="async" height="1024" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.34-4-768x1024.jpeg" width="768"><p class="aplec-2023__peu">Fotografia 10</p></div><div data-wp-media-id="17073"><img alt="2n Aplec pel Territori a Benillup · fotografia 11 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.34-5-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 11</p></div><div data-wp-media-id="17057"><img alt="2n Aplec pel Territori a Benillup · fotografia 12 de l’arxiu del 29 de gener de 2023" decoding="async" height="769" loading="lazy" src="/assets/events/aplec-2023/WhatsApp-Image-2023-01-29-at-14.51.34-1024x769.jpeg" width="1024"><p class="aplec-2023__peu">Fotografia 12</p></div><div data-wp-media-id="17050"><img alt="2n Aplec pel Territori a Benillup · fotografia 13 de l’arxiu del 29 de gener de 2023" decoding="async" height